#!/usr/bin/env python3"""Скрипт для обновления изображений агентов реальными фотографиями"""from sqlmodel import Session, selectfrom core.database import enginefrom models.agent import Agent# URL реальных изображений для агентовAGENT_IMAGES = {    "Владимир Путин": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face",    "Платон": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face",     "Фридрих Ницше": "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&h=150&fit=crop&crop=face"}def update_agent_images():    """Обновить изображения агентов"""        with Session(engine) as session:        print("=" * 80)        print("🖼️ ОБНОВЛЕНИЕ ИЗОБРАЖЕНИЙ АГЕНТОВ")        print("=" * 80)                # Получаем всех агентов        agents = session.exec(select(Agent)).all()                if not agents:            print("❌ Агенты не найдены в базе данных")            return                print(f"Найдено {len(agents)} агентов:")        for agent in agents:            print(f"- {agent.name} (ID: {agent.id})")                print("\n" + "=" * 50)        print("ОБНОВЛЕНИЕ ИЗОБРАЖЕНИЙ:")        print("=" * 50)                updated_count = 0                for agent in agents:            if agent.name in AGENT_IMAGES:                old_image = agent.image_url                agent.image_url = AGENT_IMAGES[agent.name]                session.add(agent)                                print(f"✅ {agent.name}:")                if old_image:                    print(f"   Старое: {old_image}")                else:                    print(f"   Старое: не установлено")                print(f"   Новое: {agent.image_url}")                updated_count += 1            else:                print(f"⚠️  {agent.name}: изображение не найдено в списке")                if updated_count > 0:            session.commit()            print(f"\n✅ Успешно обновлено {updated_count} изображений!")        else:            print("\n❌ Ни одно изображение не было обновлено")def add_custom_agent_image():    """Добавить изображение для конкретного агента"""        with Session(engine) as session:        agents = session.exec(select(Agent)).all()                print("=" * 80)        print("➕ ДОБАВЛЕНИЕ ИЗОБРАЖЕНИЯ ДЛЯ АГЕНТА")        print("=" * 80)                # Показываем список агентов        for i, agent in enumerate(agents, 1):            image_status = "📷" if agent.image_url else "❌"            print(f"{i}. {image_status} {agent.name} (ID: {agent.id})")            if agent.image_url:                print(f"   Текущее изображение: {agent.image_url}")                try:            choice = int(input(f"\nВыберите агента для обновления изображения (1-{len(agents)}): "))            if 1 <= choice <= len(agents):                selected_agent = agents[choice - 1]                                print(f"\nТекущее изображение для {selected_agent.name}:")                if selected_agent.image_url:                    print(f"URL: {selected_agent.image_url}")                else:                    print("Изображение не установлено")                                print("\nПримеры URL изображений:")                print("• https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&h=150&fit=crop&crop=face")                                new_image_url = input(f"\nВведите новый URL изображения для {selected_agent.name} (или Enter для удаления): ").strip()                                selected_agent.image_url = new_image_url if new_image_url else None                session.add(selected_agent)                session.commit()                                if new_image_url:                    print(f"✅ Изображение для {selected_agent.name} обновлено!")                else:                    print(f"✅ Изображение для {selected_agent.name} удалено!")            else:                print("❌ Неверный выбор!")        except ValueError:            print("❌ Введите корректный номер!")        except Exception as e:            print(f"❌ Ошибка: {e}")def main():    """Главное меню"""        while True:        print("\n" + "=" * 80)        print("🖼️ УПРАВЛЕНИЕ ИЗОБРАЖЕНИЯМИ АГЕНТОВ")        print("=" * 80)        print("1. Обновить все изображения агентов")        print("2. Добавить/изменить изображение для агента")        print("3. Просмотреть текущие изображения")        print("4. Выход")                choice = input("\nВыберите действие (1-4): ").strip()                if choice == "1":            update_agent_images()        elif choice == "2":            add_custom_agent_image()        elif choice == "3":            view_current_images()        elif choice == "4":            print("👋 До свидания!")            break        else:            print("❌ Неверный выбор")def view_current_images():    """Просмотреть текущие изображения агентов"""        with Session(engine) as session:        agents = session.exec(select(Agent)).all()                print("\n" + "=" * 80)        print("📷 ТЕКУЩИЕ ИЗОБРАЖЕНИЯ АГЕНТОВ")        print("=" * 80)                for agent in agents:            print(f"\n🤖 {agent.name} (ID: {agent.id})")            if agent.image_url:                print(f"   📷 Изображение: {agent.image_url}")            else:                print(f"   ❌ Изображение не установлено")                print(f"\nВсего агентов: {len(agents)}")if __name__ == "__main__":    main()